    #[test]
    fn load_optional_returns_empty_for_missing_file() {
        let result = EnvFileParser::load_optional(Path::new("/nonexistent/path/.env"));

        assert!(result.is_ok());
        assert!(result.unwrap().is_empty());
    }

    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    // --- Quote edge cases ---

    #[test]
    fn double_quoted_empty_value() {
        let content = r#"KEY="""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&String::new()));
    }

    #[test]
    fn single_quoted_empty_value() {
        let content = "KEY=''";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&String::new()));
    }

    #[test]
    fn inner_single_quotes_preserved_in_double_quoted_value() {
        let content = r#"KEY="it's a test""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"it's a test".to_string()));
    }

    #[test]
    fn inner_double_quotes_preserved_in_single_quoted_value() {
        let content = r#"KEY='say "hello"'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say "hello""#.to_string()));
    }

    #[test]
    fn unmatched_double_quote_not_stripped() {
        let content = r#"KEY="not closed"#;
        let vars = EnvFileParser::parse(content).unwrap();
        // Opening quote without closing quote is kept as-is
        assert_eq!(vars.get("KEY"), Some(&"\"not closed".to_string()));
    }

    #[test]
    fn unmatched_single_quote_not_stripped() {
        let content = "KEY='not closed";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'not closed".to_string()));
    }

    #[test]
    fn single_double_quote_character_value() {
        let content = r#"KEY=""#;
        let vars = EnvFileParser::parse(content).unwrap();
        // A lone quote character is returned as-is (len < 2 branch)
        assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
    }

    #[test]
    fn single_single_quote_character_value() {
        let content = "KEY='";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn backslash_sequences_in_double_quotes_preserved_literally() {
        // Backslash escapes like \n and \" are NOT interpreted; they remain literal
        let content = r#"KEY="line1\nline2""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"line1\nline2".to_string()));
    }

    #[test]
    fn backslash_escaped_quotes_inside_double_quotes() {
        // The parser does not process escape sequences, so backslashes
        // before inner quotes are preserved as literal characters
        let content = r#"KEY="say \"hi\"""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say \"hi\"#.to_string()));
    }

    #[test]
    fn backslash_tab_in_value_preserved_literally() {
        let content = r#"KEY="col1\tcol2""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"col1\tcol2".to_string()));
    }

    #[test]
    fn whitespace_inside_quotes_preserved() {
        let content = r#"KEY="  leading and trailing  ""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"  leading and trailing  ".to_string())
        );
    }

    #[test]
    fn multiple_equals_in_quoted_value() {
        let content = r#"KEY="a=b=c""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b=c".to_string()));
    }

    #[test]
    fn hash_in_unquoted_value_not_treated_as_comment() {
        // The parser does not strip inline comments; hash is part of value
        let content = "COLOR=#ff0000";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("COLOR"), Some(&"#ff0000".to_string()));
    }

    #[test]
    fn inline_comment_after_unquoted_value_included_in_value() {
        // No inline comment stripping — everything after = is the value
        let content = "KEY=value # this looks like a comment";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this looks like a comment".to_string())
        );
    }

    #[test]
    fn inline_comment_after_quoted_value_included_in_value() {
        // Quotes don't match because trailing text makes the last char not a quote
        let content = r#"KEY="value" # comment"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&r#""value" # comment"#.to_string())
        );
    }

    #[test]
    fn duplicate_keys_last_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn export_prefix_becomes_part_of_key() {
        // The parser does not strip `export` prefixes
        let content = "export KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }

    #[test]
    fn key_with_underscores_and_digits() {
        let content = "MY_APP_V2_KEY=works";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("MY_APP_V2_KEY"), Some(&"works".to_string()));
    }

    #[test]
    fn value_that_is_only_whitespace() {
        // After trim, the value becomes empty
        let content = "KEY=   ";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&String::new()));
    }

    #[test]
    fn quoted_value_containing_only_spaces() {
        let content = r#"KEY="   ""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"   ".to_string()));
    }

    #[test]
    fn mismatched_quote_types_not_stripped() {
        let content = r#"KEY="value'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        // Starts with " but ends with ' — not a matching pair
        assert_eq!(vars.get("KEY"), Some(&"\"value'".to_string()));
    }

    #[test]
    fn value_with_unicode() {
        let content = "GREETING=こんにちは";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"こんにちは".to_string()));
    }

    #[test]
