    fn value_with_unicode() {
        let content = "GREETING=こんにちは";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"こんにちは".to_string()));
    }

    #[test]
    fn quoted_value_with_unicode() {
        let content = r#"GREETING="héllo wörld""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"héllo wörld".to_string()));
    }

    #[test]
    fn empty_content_returns_empty_map() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn only_comments_and_blanks_returns_empty_map() {
        let content = "# just a comment\n\n# another\n   \n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }
}
